    expect((await store.load()).projects[0]!.tasks[0]!.runs[0]!.assignments.filter(a=>a.roleId==='worker')).toHaveLength(0);
    const guidance:any=await controller.addGuidance(run.id,'Add one brief note to README.md.');
    expect(guidance.plannerReply).toBe('Planner analysis');expect(guidance.plannerAssignmentId).toBeTruthy();expect(prompts.map(p=>p.roleId)).toEqual(['planner']);
    const result=await controller.orchestrate(run.id,'Plan the requested README note.');
