    expect(prompts.map(p=>p.roleId)).toEqual(['planner','orchestrator']);expect(prompts[1].config.previousResponseId).toBeUndefined();
    const preDispatch=await store.load(),preRun=preDispatch.projects[0]!.tasks[0]!.runs[0]!;
