  it('returns after durable approval while accepted-outcome retention remains pending',async()=>{const {controller,store,uhp}=await setup();const p:any=await controller.createProject('Async retention'),t:any=await controller.createTask(p.id,'Approved result'),r:any=await controller.createRun(t.id),worker:any=await controller.assign(r.id,'worker','implement');await store.mutate(s=>{const run=s.projects[0]!.tasks[0]!.runs[0]!;run.reviews.push({id:'review_verified',status:'verified',reviewerAssignmentId:'reviewer-proof',implementationAssignmentIds:[worker.id],verdict:'clear',scope:['all changes'],summary:'independently reviewed',createdAt:new Date().toISOString()});run.validation={id:'validation_verified',status:'passed',passed:true,reportedPassed:true,checks:[{name:'controller tests',passed:true}],gitEvidence:{status:'verified',commit:'abc123',submittedAt:new Date().toISOString()},createdAt:new Date().toISOString()};run.pinnedBaseCommit='a'.repeat(40);const storedWorker=run.assignments.find(a=>a.id===worker.id)!;storedWorker.responseId='resp_worker';run.workerEvidence={provenance:'recorded_replay',workerAssignmentId:worker.id,responseId:storedWorker.responseId,pinnedBaseCommit:run.pinnedBaseCommit,completeSnapshot:{reportedComplete:true,reportedErrors:0,entryCount:0},scopeVerified:true,allowedScope:['README.md'],entries:[],changes:[],reviewDiff:'fixture diff',acceptance:'not_decided'};run.validation.observations=[{name:'fixture check',command:'true',args:[],exitCode:0,timedOut:false,output:'passed',outputTruncated:false,startedAt:new Date().toISOString(),finishedAt:new Date().toISOString(),passed:true}];const validationEvidence={passed:true,policy:run.validation.policy,observations:run.validation.observations};run.assignments.push({id:'reviewer-proof',roleId:'reviewer',status:'succeeded',requestedConfig:{harnessId:'fixture',model:'simulated'},requestedModel:'simulated',selectedHarnessId:'fixture',reportedHarnessId:'fixture',actualModelStatus:'observed',actualConfig:{harnessId:'fixture',model:'simulated'},responseId:'resp_reviewer',sessionId:'session_reviewer',reviewerExecution:{mode:'read_only',mutationAttempted:false,validation:validationEvidence}} as any);run.reviewerRecommendation={id:'recommendation_fixture',status:'proposed',provenance:'simulated_fixture',reviewerAssignmentId:'reviewer-proof',harnessId:'fixture',model:'simulated',actualModel:'simulated',responseId:'resp_reviewer',sessionId:'session_reviewer',reviewMode:'read_only',mutationAttempted:false,verdict:'recommend',rationale:'Simulated test recommendation',createdAt:new Date().toISOString()};});let retainCalls=0;const hindsight={recall:async()=>({status:'ready' as const,bankId:'bank',memories:[]}),retainOutcome:()=>{retainCalls++;return new Promise<never>(()=>{});}};const approvedController=new Controller(store,uhp,false,false,undefined,hindsight);const approval=await Promise.race([approvedController.approveRun(r.id,{approved:true,evidenceCommit:'a'.repeat(40)}),new Promise((_,reject)=>setTimeout(()=>reject(new Error('approval waited on retention')),100))]);expect(approval).toMatchObject({approved:true,evidenceCommit:'a'.repeat(40)});const snapshot=await store.load();const intent=snapshot.events.find(e=>e.type==='memory.retention_intent');expect(intent?.data).toMatchObject({retentionId:worker.submissionId,idempotencyReference:`foreman-submission-${worker.submissionId}`,status:'pending'});await new Promise(resolve=>setTimeout(resolve,0));expect(retainCalls).toBe(1);await expect(approvedController.approveRun(r.id,{approved:true,evidenceCommit:'a'.repeat(40)})).rejects.toThrow('human decision is final');expect(retainCalls).toBe(1);});
  it('retries degraded retained outcomes after restart using the same idempotency reference',async()=>{const {controller,store,uhp}=await setup();const p:any=await controller.createProject('Retention retry'),t:any=await controller.createTask(p.id,'Approved outcome'),r:any=await controller.createRun(t.id),worker:any=await controller.assign(r.id,'worker','implement');await store.mutate(s=>{const run=s.projects[0]!.tasks[0]!.runs[0]!;run.reviews.push({id:'review_verified',status:'verified',reviewerAssignmentId:'reviewer-proof',implementationAssignmentIds:[worker.id],verdict:'clear',scope:['all changes'],summary:'independently reviewed',createdAt:new Date().toISOString()});run.validation={id:'validation_verified',status:'passed',passed:true,reportedPassed:true,checks:[{name:'controller tests',passed:true}],gitEvidence:{status:'verified',commit:'abc123',submittedAt:new Date().toISOString()},createdAt:new Date().toISOString()};run.pinnedBaseCommit='a'.repeat(40);const storedWorker=run.assignments.find(a=>a.id===worker.id)!;storedWorker.responseId='resp_worker';run.workerEvidence={provenance:'recorded_replay',workerAssignmentId:worker.id,responseId:storedWorker.responseId,pinnedBaseCommit:run.pinnedBaseCommit,completeSnapshot:{reportedComplete:true,reportedErrors:0,entryCount:0},scopeVerified:true,allowedScope:['README.md'],entries:[],changes:[],reviewDiff:'fixture diff',acceptance:'not_decided'};run.validation.observations=[{name:'fixture check',command:'true',args:[],exitCode:0,timedOut:false,output:'passed',outputTruncated:false,startedAt:new Date().toISOString(),finishedAt:new Date().toISOString(),passed:true}];const validationEvidence={passed:true,policy:run.validation.policy,observations:run.validation.observations};run.assignments.push({id:'reviewer-proof',roleId:'reviewer',status:'succeeded',requestedConfig:{harnessId:'fixture',model:'simulated'},requestedModel:'simulated',selectedHarnessId:'fixture',reportedHarnessId:'fixture',actualModelStatus:'observed',actualConfig:{harnessId:'fixture',model:'simulated'},responseId:'resp_reviewer',sessionId:'session_reviewer',reviewerExecution:{mode:'read_only',mutationAttempted:false,validation:validationEvidence}} as any);run.reviewerRecommendation={id:'recommendation_fixture',status:'proposed',provenance:'simulated_fixture',reviewerAssignmentId:'reviewer-proof',harnessId:'fixture',model:'simulated',actualModel:'simulated',responseId:'resp_reviewer',sessionId:'session_reviewer',reviewMode:'read_only',mutationAttempted:false,verdict:'recommend',rationale:'Simulated test recommendation',createdAt:new Date().toISOString()};});const unavailable={recall:async()=>({status:'ready' as const,bankId:'bank',memories:[]}),retainOutcome:async()=>({status:'degraded' as const,bankId:'bank',error:'temporary outage'})};const approving=new Controller(store,uhp,false,false,undefined,unavailable);await approving.approveRun(r.id,{approved:true,evidenceCommit:'a'.repeat(40)});let state=await store.load();for(let i=0;i<100&&!state.events.some(e=>e.type==='memory.retention_attempt_failed');i++){await new Promise(resolve=>setTimeout(resolve,2));state=await store.load();}expect(state.events.some(e=>e.type==='memory.retention_attempt_failed')).toBe(true);expect(state.events.some(e=>e.type==='memory.retention_completed')).toBe(false);const restartedStore=new JsonStore(store.filePath);let retries=0;const recovered=new Controller(restartedStore,uhp,false,false,undefined,{recall:unavailable.recall,retainOutcome:async outcome=>{retries++;expect(outcome.submissionId).toBe(worker.submissionId);return {status:'accepted',bankId:'bank',operationId:'op-retry'};}});await recovered.resumePendingRetentions();expect(retries).toBe(1);state=await restartedStore.load();for(let i=0;i<100&&!state.events.some(e=>e.type==='memory.retention_completed');i++){await new Promise(resolve=>setTimeout(resolve,2));state=await restartedStore.load();}expect(state.events.find(e=>e.type==='memory.retention_intent')?.data.idempotencyReference).toBe(`foreman-submission-${worker.submissionId}`);expect(state.events.find(e=>e.type==='memory.retention_completed')?.data).toMatchObject({retentionId:worker.submissionId,status:'accepted',operationId:'op-retry'});});
  it('records terminal completion when cancellation races with a completed UHP response',async()=>{let release!:()=>void,started!:()=>void;const gate=new Promise<void>(resolve=>{release=resolve;}),created=new Promise<void>(resolve=>{started=resolve;});const {controller,store}=await setup({submit:async input=>{await input.onEvent?.({type:'response.created',responseId:'race-response',event:{type:'response.created'}});started();await gate;return {externalId:'race-response',responseId:'race-response',status:'completed',result:'completed before cancel'};},cancel:async()=>({status:'completed'})});const p:any=await controller.createProject('Cancel race'),t:any=await controller.createTask(p.id,'Completed during cancel'),r:any=await controller.createRun(t.id);const assignmentPromise=controller.assign(r.id,'worker','finish task');await created;const assignment=(await store.load()).projects[0]!.tasks[0]!.runs[0]!.assignments[0]!;const canceled:any=await controller.cancelAssignment(assignment.id);expect(canceled.status).toBe('succeeded');expect((await store.load()).events.some(e=>e.type==='assignment.cancel_raced_terminal'&&e.data.source==='cancel-response')).toBe(true);release();await expect(assignmentPromise).resolves.toMatchObject({status:'succeeded',result:'completed before cancel'});});
